cat <<'EOF' > test_comprehensive.py
import pandas as pd

def test_flags_keyerror():
    df = pd.DataFrame()
    flags = df.flags

    print("=== Testing __getitem__ with invalid key ===")
    try:
        flags['invalid_flag']
        print("ERROR: No exception raised!")
    except KeyError as e:
        print(f"SUCCESS: KeyError raised as expected: {e}")
    except Exception as e:
        print(f"ERROR: Wrong exception type: {type(e).__name__}: {e}")

    print("\n=== Testing __setitem__ with invalid key ===")
    try:
        flags['invalid_flag'] = True
        print("ERROR: No exception raised!")
    except KeyError as e:
        print(f"SUCCESS: KeyError raised as expected: {e}")
    except Exception as e:
        print(f"ERROR: Wrong exception type: {type(e).__name__}: {e}")

    print("\n=== Testing __getitem__ with valid key ===")
    try:
        result = flags['allows_duplicate_labels']
        print(f"SUCCESS: Valid key access works: {result}")
    except Exception as e:
        print(f"ERROR: Valid key access failed: {type(e).__name__}: {e}")

    print("\n=== Testing __setitem__ with valid key ===")
    try:
        flags['allows_duplicate_labels'] = False
        result = flags['allows_duplicate_labels']
        print(f"SUCCESS: Valid key setting works: {result}")
    except Exception as e:
        print(f"ERROR: Valid key setting failed: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_flags_keyerror()
EOF

